def split_writers(apps, schema_editor):  # noqa: ARG001
    """Existing writers' names into first and last, as cue sheets split them.

    'Casey J. Composer' -> ('Casey J.', 'Composer'); 'van der Berg, Ann'
    -> ('Ann', 'van der Berg').
    """
    party = apps.get_model("cues", "Party")
    for writer in party.objects.filter(kind="writer"):
        name = " ".join(writer.name.split())
        if "," in name:
            last, first = (part.strip() for part in name.split(",", 1))
        else:
            first, _, last = name.rpartition(" ")
        writer.first_name, writer.last_name = first, last
        writer.name = f"{first} {last}".strip()
        writer.save(update_fields=["first_name", "last_name", "name"])


